    private File createSecureTempDirectory() throws IOException {
        FileAttribute<Set<PosixFilePermission>> attr = null;
        File tempDir;
        if(System.getProperty("os.name").toLowerCase().contains("win")) {
            tempDir = Files.createTempDirectory("tmp").toFile();
            tempDir.setReadable(true, true);
